<template><div class="app-container" v-loading="loading"><h3>个人与团队协作</h3><el-alert title="默认直接发布。多人账号不自动开启审核，单人也不必分配询盘。策略变更不会修改当前线上内容；受影响的待审核/批准和待发布定时任务会失效/取消。" :closable="false"/><el-tabs v-model="tab" :before-leave="()=>!busy" @tab-change="tabChanged"><el-tab-pane label="协作规则" name="rules"><el-form v-if="state" label-width="140px" style="max-width:860px;margin-top:20px"><el-form-item v-for="(v,k) in kindLabels" :key="k" :label="v+'发布'"><el-switch v-model="required[k]" active-text="需其他人审核" inactive-text="直接发布"/></el-form-item><el-divider/><el-form-item label="询盘负责人隔离"><el-switch v-model="isolation"/><p>开启后普通处理人仅能查看分配给自己的询盘。具备“全部询盘范围”或“询盘指派”的账号可见全部；不自动向角色授权。</p></el-form-item><el-form-item label="新询盘接收人"><WorkflowPersonPicker v-model="managers" multiple/><p>当前ID：{{managers.join('、')||'不提醒'}}。仅接收通用站内消息，不推送客户原文。</p></el-form-item><el-form-item label="变更原因" required><el-input v-model="reason" type="textarea" maxlength="500" placeholder="说明本次策略或范围调整原因"/></el-form-item><el-form-item><el-button v-hasPermi="['cms:workflow:edit']" type="primary" :loading="busy" @click="save">保存协作策略</el-button><el-button @click="load">重新读取</el-button></el-form-item></el-form></el-tab-pane><el-tab-pane label="影响范围" name="impact"><el-table :data="impact"><el-table-column label="模块"><template #default="s">{{kindLabels[s.row.kind]}}</template></el-table-column><el-table-column prop="pending" label="待审核"/><el-table-column prop="approved" label="批准未使用"/><el-table-column prop="scheduled" label="待发布定时任务"/></el-table><p>数量为读取时快照；保存时后端重验当前策略及全部受影响记录。待下架任务不受影响。</p></el-tab-pane><el-tab-pane label="变更记录" name="history"><el-table :data="history"><el-table-column prop="actorUserId" label="操作人ID" width="110"/><el-table-column prop="reason" label="变更原因"/><el-table-column prop="createTime" label="时间" width="170"/></el-table><pagination v-if="total" :total="total" v-model:page="pg.pageNum" v-model:limit="pg.pageSize" @pagination="loadHistory"/></el-tab-pane></el-tabs></div></template>
<script setup>
import{ref,reactive,onMounted,onBeforeUnmount,onDeactivated,onActivated}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import{workflow,kindLabels}from'@/api/cms/workflow';import WorkflowPersonPicker from '../components/WorkflowPersonPicker.vue'
const tab=ref('rules'),impact=ref([]),state=ref(),required=reactive({ARTICLE:false,PRODUCT:false,PAGE:false,SITE:false}),isolation=ref(false),managers=ref([]),reason=ref(''),busy=ref(false),loading=ref(false),history=ref([]),total=ref(0),pg=reactive({pageNum:1,pageSize:10});let epoch=0
async function load(){const n=++epoch;loading.value=true;try{const [r,i]=await Promise.all([workflow('workflow/settings'),workflow('workflow/impact')]);if(n===epoch){impact.value=i.data;state.value=r.data;isolation.value=r.data.inquiryIsolation;managers.value=r.data.managerIds||[];for(const p of r.data.policies)required[p.kind]=p.required;reason.value=''}}finally{if(n===epoch)loading.value=false}}
async function tabChanged(){if(tab.value==='history')await loadHistory();else if(tab.value==='impact'){const n=epoch,r=await workflow('workflow/impact');if(n===epoch)impact.value=r.data}}
async function loadHistory(){const n=epoch,r=await workflow('workflow/history','get',undefined,{...pg});if(n===epoch){history.value=r.rows;total.value=r.total}}
async function save(){if(busy.value)return;const n=epoch;if(!reason.value.trim()){ElMessage.warning('请填写变更原因');return};const changed=state.value.policies.filter(p=>p.required!==required[p.kind]).map(p=>kindLabels[p.kind]);try{await ElMessageBox.confirm(`改变发布策略：${changed.join('、')||'无'}。影响数量：${impact.value.filter(p=>changed.includes(kindLabels[p.kind])).map(p=>`${kindLabels[p.kind]} 待审${p.pending}/批准${p.approved}/定时${p.scheduled}`).join('；')||'无'}。这些模块的待审核/批准会失效，待发布定时任务会取消；询盘隔离同时立即生效。确认保存？`,'策略变更确认',{type:'warning'});if(n!==epoch)return;busy.value=true;await workflow('workflow/settings','put',{version:state.value.version,required:{...required},inquiryIsolation:isolation.value,managerIds:managers.value,reason:reason.value});if(n!==epoch)return;ElMessage.success('协作策略已保存');await load();await loadHistory()}catch{}finally{busy.value=false}}
onMounted(load);function close(){++epoch}onBeforeUnmount(close);let resumed=false;onDeactivated(()=>{resumed=true;close()});onActivated(()=>{if(resumed){resumed=false;load().then(()=>tab.value==='history'&&loadHistory())}})
</script>
